/*
 * S-95 question bank, written against the FDNY S-95 Study Material (rev. October 2026).
 * Format: { id, t: topicId, q, a: correct answer, w: [3 wrong answers], e: explanation, ref: booklet section }
 * Choices are shuffled at runtime, so never write "all of the above" / "A and B".
 * The real exam uses 4 choices per question, so every item has exactly 3 distractors.
 */
window.S95 = window.S95 || {};
S95.questions = [
/* ================= Exam & certificate rules ================= */
{ id:"x1", t:"exam", ref:"p.5", q:"How many questions are on the S-95 exam?", a:"35", w:["25","50","100"],
  e:"The S-95 exam has 35 multiple-choice questions, taken on a touch-screen computer." },
{ id:"x2", t:"exam", ref:"p.5", q:"How much time are you given to complete the S-95 exam?", a:"53 minutes", w:["30 minutes","90 minutes","2 hours"],
  e:"Based on the number of questions, candidates get 53 minutes." },
{ id:"x3", t:"exam", ref:"p.5, 8", q:"What score is needed to pass the S-95 exam?", a:"At least 70%", w:["At least 60%","At least 75%","At least 80%"],
  e:"A passing score of at least 70% is required to get the Certificate of Fitness." },
{ id:"x4", t:"exam", ref:"p.8", q:"How is a question you leave unanswered scored?", a:"As incorrect", w:["It is skipped and not counted","As half credit","It is re-asked at the end"],
  e:"Unanswered questions are scored as incorrect, and there is no penalty for guessing. Always answer every question." },
{ id:"x5", t:"exam", ref:"p.9", q:"Which of the following may be used during a Certificate of Fitness exam at 9 MetroTech Center?", a:"Reference material provided by the FDNY", w:["Your own study material booklet","A cellular phone","An mp3 player"],
  e:"Only reference material provided by the FDNY is allowed during the exam." },
{ id:"x6", t:"exam", ref:"p.9", q:"Your computer screen freezes during the exam. Whom should you ask for help?", a:"The examiner in the testing room", w:["The person next to you","The firefighters in the testing room","The computer help desk"],
  e:"Ask the examiner in the testing room about computer problems." },
{ id:"x7", t:"exam", ref:"p.9", q:"You don't know the answer to an exam question. What should you do?", a:"Not ask anyone, since FDNY staff cannot assist applicants with test questions", w:["Ask the examiner","Ask the person next to you","Ask a firefighter in the room"],
  e:"FDNY staff cannot help with exam questions or answers." },
{ id:"x8", t:"exam", ref:"p.4", q:"Before arriving at the FDNY for the exam, applicants must:", a:"Apply and pay for the exam online", w:["Mail a paper application","Get a letter from the Fire Commissioner","Complete a hands-on panel test"],
  e:"All applicants must apply and pay online before arriving. It takes about 30 minutes." },
{ id:"x9", t:"exam", ref:"p.4", q:"You failed the S-95 exam this morning. When can you retest?", a:"Not on the same calendar day; a new application and payment are required", w:["Right away, at no extra cost","After lunch on the same day, with the same application","Only after 6 months"],
  e:"Each testing opportunity needs a separate application and payment, and retesting on the same calendar day is not permitted." },
{ id:"x10", t:"exam", ref:"p.4", q:"What convenience fee applies to card payments for the exam?", a:"2%", w:["5%","$10 flat","There is no fee"],
  e:"A 2% convenience fee applies to all card payments." },
{ id:"x11", t:"exam", ref:"p.5", q:"Who is eligible for an exam fee waiver?", a:"Government employees who will use the certificate for their work responsibilities", w:["Anyone who is unemployed","Students","Building owners"],
  e:"Only government employees using the certificate for work are eligible. They need a letter on agency letterhead and a copy of their agency ID." },
{ id:"x12", t:"exam", ref:"p.4", q:"Holders of which certificates are exempt from getting a separate S-95 for the same premises?", a:"F-89/T-89, F-80, or F-53", w:["S-12 or S-15","W-96 or W-27","G-60 or G-35"],
  e:"F-89/T-89 (Fire Life Safety Director), F-80 and F-53 holders are exempt from a separate S-95 for the same premises." },
{ id:"x13", t:"exam", ref:"p.4", q:"An F-89 holder wants an S-95 for a different premises. What is required?", a:"An employer recommendation letter and the $25 payment, but no exam", w:["The full S-95 exam","Nothing at all","A new F-89 exam"],
  e:"They can get the S-95 for a different premises without taking the exam, but the recommendation letter and $25 fee are still required." },
{ id:"x14", t:"exam", ref:"§1", q:"A fire alarm system in a commercial high-rise building must be supervised by which certificate holder?", a:"Fire Life Safety Director (FLSD)", w:["S-95","F-53","F-80"],
  e:"Fire alarm systems in commercial or mixed-use high-rise buildings need an FLSD." },
{ id:"x15", t:"exam", ref:"§1", q:"Which fire alarm system is supervised by an S-95 holder?", a:"A system without a voice communication system that does not require an FLSD, F-80 or F-53", w:["A system with two-way voice communication and warden phones","A system in a homeless shelter","A hotel system with 60 sleeping rooms above the ground floor and voice communication"],
  e:"The S-95 covers fire alarm systems without voice communication where no FLSD, F-80 or F-53 is required." },
{ id:"x16", t:"exam", ref:"§1", q:"A fire alarm system with a one-way communication (public announcement) system, not requiring an FLSD or F-80, needs which certificate holder?", a:"F-53", w:["S-95","F-80","S-98"],
  e:"F-53 is Emergency One-Way Voice Announcement Personnel." },
{ id:"x17", t:"exam", ref:"§1", q:"What does the F-80 Certificate of Fitness cover?", a:"Coordinator of Fire Safety and Alarm System in Homeless Shelters", w:["Fire Life Safety Director","Emergency One-Way Voice Announcement Personnel","Fire Guard for Impairment"],
  e:"The F-80 covers fire alarm systems in homeless shelters that don't need an FLSD." },
{ id:"x18", t:"exam", ref:"§1", q:"A hotel fire alarm system with one- or two-way communication must be supervised by an FLSD when the hotel has at least how many sleeping rooms above the ground floor?", a:"50", w:["10","25","100"],
  e:"Hotels with 50 or more sleeping rooms above the ground floor, with one- or two-way communication, need an FLSD." },
{ id:"x19", t:"exam", ref:"§1", q:"What document shows that a premises' fire alarm system is approved by the FDNY?", a:"An FDNY Letter of Approval", w:["A Certificate of Occupancy only","A central station invoice","The manufacturer's warranty"],
  e:"Certificate holders should make sure their premises' fire alarm systems are approved by an FDNY Letter of Approval." },
{ id:"x20", t:"exam", ref:"p.7", q:"What are the special renewal requirements for the S-95 Certificate of Fitness?", a:"There are none", w:["Retake the exam every 3 years","Complete 8 hours of continuing education","Get a new employer letter every year"],
  e:"The booklet states: Special renewal requirements, S-95 Certificate of Fitness: None. The FDNY recommends renewing online." },
{ id:"x21", t:"exam", ref:"p.8", q:"How many answer choices does each Certificate of Fitness exam question have?", a:"Four", w:["Two","Three","Five"],
  e:"All questions are multiple choice with four answers, and only one is correct." },

/* ================= Definitions ================= */
{ id:"df1", t:"defs", ref:"§1.1", q:"What is an ALARM SIGNAL?", a:"A signal indicating an emergency requiring immediate action, such as a fire", w:["A signal indicating a fault in a monitored circuit","A signal that a sprinkler valve is closed","A signal indicating routine maintenance is due"],
  e:"An alarm signal indicates an emergency requiring immediate action, such as a signal indicating fire." },
{ id:"df2", t:"defs", ref:"§1.1", q:"What is the difference between a smoke ALARM and a smoke DETECTOR?", a:"A smoke alarm is not connected to a fire alarm system; a smoke detector is", w:["A smoke detector is battery-only; a smoke alarm is hard-wired","There is no difference","A smoke alarm detects heat; a smoke detector detects smoke"],
  e:"A smoke alarm is a single- or multiple-station alarm not connected to a fire alarm system. A smoke detector is connected to a fire alarm system." },
{ id:"df3", t:"defs", ref:"§1.1", q:"An alarm caused by a system that worked as designed, but for which an FDNY response proved unnecessary, is called a(n):", a:"Unnecessary alarm", w:["Unwarranted alarm","Nuisance alarm","Malicious alarm"],
  e:"Unnecessary alarm: the system functioned as designed, but no response was needed. Example: smoke from a lit cigarette in a non-smoking area." },
{ id:"df4", t:"defs", ref:"§1.1", q:"An alarm caused by improper smoke detector placement or lack of system maintenance is called a(n):", a:"Unwarranted alarm", w:["Unnecessary alarm","Supervisory alarm","Verified alarm"],
  e:"Unwarranted alarms happen when the system failed to work as designed: improper installation, improper maintenance, malfunction, and so on." },
{ id:"df5", t:"defs", ref:"§1.1", q:"What feature reduces the number of unwarranted alarms?", a:"Alarm verification", w:["Alarm silence","Lamp test","Partial evacuation"],
  e:"The booklet notes that the alarm verification feature reduces unwarranted alarms." },
{ id:"df6", t:"defs", ref:"§1.1", q:"Any alarm activated by a cause that cannot be determined is classified as a(n):", a:"Nuisance alarm", w:["Unnecessary alarm","Supervisory signal","Trouble signal"],
  e:"A nuisance alarm is caused by mechanical failure, malfunction, improper installation, lack of maintenance, or a cause that cannot be determined." },
{ id:"df7", t:"defs", ref:"§1.1", q:"What does 'SHALL' mean in the Fire Code and study material?", a:"A mandatory requirement", w:["A recommendation","An optional practice","A requirement only for new buildings"],
  e:"SHALL means mandatory. SHOULD means recommended but not required." },
{ id:"df8", t:"defs", ref:"§1.1", q:"What does 'SHOULD' mean in the study material?", a:"Something recommended or advised, but not required", w:["A mandatory requirement","A requirement enforced only by the central station","A legal prohibition"],
  e:"SHOULD indicates a recommendation, not a requirement." },
{ id:"df9", t:"defs", ref:"§1.1", q:"What is a PLENUM?", a:"The open space that carries air between the ceiling and the floor above", w:["A sealed sprinkler pipe","The space inside the FACP cabinet","A stairwell used for pressurization"],
  e:"A plenum is the open space between the ceiling and the floor above that carries air." },
{ id:"df10", t:"defs", ref:"§1.1", q:"An APPROVED CENTRAL STATION COMPANY is one that:", a:"Has a valid certificate of operation from the FDNY", w:["Is listed in the phone book","Is owned by the building owner","Is located in the same building"],
  e:"An approved central station company has been issued a valid certificate of operation by the FDNY." },
{ id:"df11", t:"defs", ref:"§1.1", q:"What is ARCS?", a:"An in-building wireless two-way radio system for Fire Department use only", w:["An automatic sprinkler control valve","A smoke purge fan system","The central station's computer software"],
  e:"ARCS (Auxiliary Radio Communication System) is a two-way building radio system for FDNY use only." },
{ id:"df12", t:"defs", ref:"§1.1", q:"Who is the DESIGNATED REPRESENTATIVE?", a:"The person the subscriber designates to receive central station notifications and act on the system", w:["The FDNY inspector assigned to the building","The fire alarm manufacturer's sales representative","The central station operator on duty"],
  e:"The designated representative receives notifications from the central station about the system's status and is authorized to act on it." },
{ id:"df13", t:"defs", ref:"§1.1", q:"A remote annunciator panel, when installed, functions for:", a:"Visual notification of alarm, supervisory or trouble conditions only", w:["Silencing and resetting the fire alarm system","Voice announcements to all floors","Testing smoke detectors"],
  e:"By definition, a remote annunciator panel is for visual notification only." },
{ id:"df14", t:"defs", ref:"§1.1", q:"A PROTECTED PREMISES is a building with a fire alarm system that transmits to the FDNY or a central station:", a:"Whether or not the system is required by law", w:["Only if the system is required by law","Only if it is a high-rise","Only if it has sprinklers"],
  e:"Protected premises include buildings whose systems transmit alarms, whether or not the installation is required by law." },
{ id:"df15", t:"defs", ref:"§1.1", q:"What is a DEFINED FIRE ALARM SYSTEM?", a:"A system that automatically transmits signals to the FDNY or a central station, in premises required to have a fire alarm system", w:["Any system with a written description","A local-only system that rings bells in the building","A system that only uses manual pull stations"],
  e:"A defined fire alarm system automatically transmits signals and is installed in premises required to have a fire alarm system." },
{ id:"df16", t:"defs", ref:"§1.1", q:"What is the LAMP TEST function used for?", a:"Checking the condition of the LEDs on the FACP", w:["Testing the building's emergency lighting","Testing the strobes on every floor","Testing smoke detector sensitivity"],
  e:"Lamp test checks the light-emitting diodes on the FACP." },
{ id:"df17", t:"defs", ref:"§1.1", q:"An OUT-OF-SERVICE SYSTEM is a fire protection system that:", a:"Is not fully functional, or whose operation is impaired or not in good working order", w:["Has been removed from the building entirely","Is turned off only at night","Is waiting for its annual inspection"],
  e:"A system that is not fully functional, impaired, or not in good working order is out of service." },
{ id:"df18", t:"defs", ref:"§1.1", q:"Which is an example of an INITIATING DEVICE?", a:"A supervisory switch", w:["A horn/strobe","A warden phone speaker","A remote annunciator"],
  e:"Initiating devices start a change-of-state signal: smoke detectors, manual fire alarm boxes and supervisory switches." },
{ id:"df19", t:"defs", ref:"§1.1", q:"According to the definitions, a TROUBLE SIGNAL must be investigated and corrected by:", a:"An approved company", w:["The FDNY","Any building occupant","The central station operator"],
  e:"A trouble signal indicates a fault in a monitored circuit or component, and must be investigated and corrected by an approved company." },
{ id:"df20", t:"defs", ref:"§1.1", q:"Which is an ALARM NOTIFICATION APPLIANCE?", a:"A vibration device that gives a tactile alert", w:["A waterflow switch","A valve tamper switch","A heat detector"],
  e:"Notification appliances include bells, horns, speakers, lights, text displays and vibration devices." },
{ id:"df21", t:"defs", ref:"§1.1", q:"'Accessibility' as defined by NFPA means:", a:"Admitting close approach: not guarded by locked doors, elevation, and other effective means", w:["Available only to the FDNY","Located on the ground floor","Wheelchair accessible only"],
  e:"This is the NFPA definition, used for devices that need cleaning and testing." },

/* ================= Signals ================= */
{ id:"s1", t:"signals", ref:"§3.2", q:"What type of signal does a sprinkler waterflow switch send?", a:"Fire alarm signal", w:["Supervisory signal","Trouble signal","No signal; it only rings a local bell"],
  e:"Waterflow devices send a fire alarm signal, sound the alarm, and recall elevators." },
{ id:"s2", t:"signals", ref:"§3.2.2", q:"A valve supervisory switch on a sprinkler system activates. What signal results?", a:"Supervisory signal", w:["Fire alarm signal","Trouble signal","Carbon monoxide signal"],
  e:"Valve supervisory (tamper) switches generate supervisory signals." },
{ id:"s3", t:"signals", ref:"§3.2.3", q:"Which is a common TROUBLE condition monitored by an FACP?", a:"A ground fault", w:["A pull station activation","Low air pressure in a dry-pipe system","A fire pump running"],
  e:"Common trouble conditions: battery condition, AC failure, ground fault, open or short circuit, phone line failure, internal component failure." },
{ id:"s4", t:"signals", ref:"§3.2.3", q:"Trouble signals indicate that:", a:"The alarm system, transmitter, or communications path is wholly or partially out of service", w:["A fire has been detected","A sprinkler valve is closed","The FDNY is on the way"],
  e:"This is the booklet's description of a trouble signal." },
{ id:"s5", t:"signals", ref:"§3.1", q:"Does the FDNY respond to supervisory signals?", a:"No, the FDNY does not respond to supervisory signals", w:["Yes, always with a full assignment","Yes, but only at night","Only if the building is a high-rise"],
  e:"The booklet states that the FDNY does not respond to supervisory signals, which may not flag a fire condition." },
{ id:"s6", t:"signals", ref:"§3.2.1", q:"In what order must central station operators process signals?", a:"Fire alarm signals before any other signals, regardless of the order received", w:["In the order they were received","Trouble signals first","Supervisory signals first"],
  e:"Fire alarm signals always come first." },
{ id:"s7", t:"signals", ref:"§3.2.1", q:"When must the central station retransmit a fire alarm signal to the FDNY?", a:"Immediately upon receipt of the signal", w:["After calling the premises to confirm","Within 4 minutes","Only if the alarm does not restore by itself"],
  e:"Alarm signals are retransmitted immediately. The operator notifies the premises afterward." },
{ id:"s8", t:"signals", ref:"§3.2.1", q:"A fire alarm signal is received at the central station and restores automatically a few seconds later. What must the central station do?", a:"Still retransmit it immediately to the FDNY as a fire alarm signal", w:["Ignore it, since it restored","Call the building first, and retransmit only if fire is confirmed","Log it as a trouble signal"],
  e:"EVERY fire alarm signal must be retransmitted to the FDNY, even if it automatically restores. There are NO EXCEPTIONS." },
{ id:"s9", t:"signals", ref:"§3.2.1", q:"A signal is deemed 'received' at the central station when:", a:"It is processed by the automation software", w:["An operator reads it aloud","The building calls to confirm it","It has been displayed for 60 seconds"],
  e:"A signal counts as received when the central station's automation software processes it." },
{ id:"s10", t:"signals", ref:"§3.2.1", q:"When the central station retransmits an alarm to the FDNY, what must it indicate?", a:"The type of alarm received (automatic, valve, manual, or carbon monoxide)", w:["Only the building's zip code","The name of the S-95 holder","The make of the fire alarm panel"],
  e:"Alarm signals sent to the FDNY must indicate the type: automatic, valve, manual or carbon monoxide." },
{ id:"s11", t:"signals", ref:"§3.2.3", q:"What is the maximum time for routine handling, from the central station receiving a trouble signal to starting the investigation by telephone?", a:"4 minutes", w:["30 seconds","15 minutes","1 hour"],
  e:"Routine handling should take a maximum of four minutes." },
{ id:"s12", t:"signals", ref:"§3.2.3", q:"When the central station receives a trouble signal, whom must it contact immediately?", a:"Persons designated by the subscriber", w:["The FDNY borough dispatcher","The building's tenants","The Department of Buildings"],
  e:"For trouble signals, the central station communicates immediately with the subscriber's designated persons." },
{ id:"s13", t:"signals", ref:"§3.2.2", q:"Which device generates a SUPERVISORY signal?", a:"A high/low water level switch on a gravity tank feeding a sprinkler system", w:["A manual pull station","A smoke detector","A waterflow switch"],
  e:"Tank water level switches are supervisory devices." },
{ id:"s14", t:"signals", ref:"§3.2.2", q:"Fire pump phase reversal generates which type of signal?", a:"Supervisory", w:["Fire alarm","Trouble","No signal"],
  e:"Fire pump running, pump failure and phase reversal are supervisory signals." },
{ id:"s15", t:"signals", ref:"§3.2.1", q:"When a fire alarm signal is generated, which of the following does the FACP NOT do?", a:"Automatically shut off the building's water supply", w:["Activate the building's horns and strobes","Send a signal to the FDNY-approved central station","Activate control of certain building functions"],
  e:"On a fire alarm the FACP activates audible/visual devices, signals the central station, and controls building functions. It does not shut off water." },
{ id:"s16", t:"signals", ref:"§2", q:"What is the PRIMARY purpose of fire alarm systems within protected premises?", a:"To warn occupants and transmit fire signals to the FDNY through an FDNY-approved central station", w:["To extinguish fires automatically","To record building entry and exit","To control the building's heating system"],
  e:"This is stated in bold in Booklet §2." },
{ id:"s17", t:"signals", ref:"§3.2.3", q:"A phone line failure on the central station connection produces which signal?", a:"Trouble", w:["Fire alarm","Supervisory","Waterflow"],
  e:"Phone line failure is listed as a common trouble condition." },
{ id:"s18", t:"signals", ref:"§3.2.2", q:"A supervisory signal will:", a:"Annunciate audibly and visually at the FACP and be sent to the FDNY-approved central station", w:["Sound all building horns and evacuate the building","Be displayed only at the central station","Automatically dispatch the FDNY"],
  e:"Supervisory signals sound and light at the FACP and are transmitted to the central station." },

/* ================= FACP controls & alarm response ================= */
{ id:"f1", t:"facp", ref:"§4.4", q:"When may the fire alarm panel be reset after a fire alarm?", a:"Only after the alarm condition is verified by FDNY personnel, at their direction", w:["As soon as the S-95 decides it is false","After 15 minutes","Whenever the central station calls"],
  e:"DO NOT SILENCE BUILDING AUDIBLE/VISUAL DEVICES OR RESET THE PANEL UNTIL THE FIRE ALARM CONDITION IS VERIFIED BY FDNY PERSONNEL." },
{ id:"f2", t:"facp", ref:"§4.3", q:"Does pressing ALARM SILENCE stop the signal from being transmitted to the central station?", a:"No, silence does not prevent transmission to the central station", w:["Yes, it cancels the central station signal","Yes, but only for supervisory signals","Only if pressed within 30 seconds"],
  e:"The silence switch does not prevent a signal from being transmitted to the FDNY-approved central station." },
{ id:"f3", t:"facp", ref:"§4.3", q:"Depending on the system, ALARM SILENCE may:", a:"Silence only the audible alarm while strobes continue to flash", w:["Reset all detectors","Turn off the AC power","Disconnect the central station"],
  e:"It either silences the notification appliances completely, or only the audibles, with strobes still flashing." },
{ id:"f4", t:"facp", ref:"§4.3", q:"What is one purpose of silencing the audible alarm once evacuation is complete?", a:"To make communication easier for emergency responders", w:["To cancel the FDNY response","To reset the detectors","To test the batteries"],
  e:"Audible silence allows easier communication for responders while the source is investigated." },
{ id:"f5", t:"facp", ref:"§4.4", q:"You press SYSTEM RESET but a smoke detector is still sensing smoke. What happens?", a:"Another alarm will be generated", w:["The panel resets to normal anyway","The detector is automatically bypassed","The central station cancels the alarm"],
  e:"If an initiating device is still in alarm after reset, another alarm is generated." },
{ id:"f6", t:"facp", ref:"§4.4", q:"After a fire alarm is reset, building fans usually:", a:"Must be restarted with a separate 'fan restart' button or key switch", w:["Restart automatically","Stay off until the next annual inspection","Can only be restarted by the FDNY"],
  e:"The fan usually needs restarting from a separate fan restart button or key switch." },
{ id:"f7", t:"facp", ref:"§4.4", q:"Most trouble and supervisory conditions:", a:"Clear automatically when conditions return to normal", w:["Must be reset by the FDNY","Never clear without replacing the panel","Clear when the ACK button is pressed"],
  e:"Most trouble and supervisory conditions clear automatically when conditions return to normal." },
{ id:"f8", t:"facp", ref:"§4.2", q:"The ACKNOWLEDGE (ACK) button is used to:", a:"Acknowledge alarm, trouble or supervisory conditions", w:["Reset the system","Cancel the FDNY response","Test the panel LEDs"],
  e:"ACK acknowledges alarm, trouble or supervisory conditions. Sequences vary by system." },
{ id:"f9", t:"facp", ref:"§4.2", q:"When an alarm activates, where should the certificate holder report, when present and practical?", a:"To the FACP location", w:["To the roof","Outside, to wait for the FDNY","To the alarm floor to look for fire before doing anything else"],
  e:"It is important for the certificate holder to report to the FACP whenever the alarm activates, when present and practical." },
{ id:"f10", t:"facp", ref:"§4.1", q:"For an alarm, what must the S-95 record in the log book?", a:"The date and time, location, which device activated, and the probable cause", w:["Only the date","Only the name of the person who discovered it","The weather and outdoor temperature"],
  e:"Booklet §4.1 lists date/time, location, activated device, and probable cause." },
{ id:"f11", t:"facp", ref:"§4.4", q:"Can an FACP in alarm be reset to 'normal' while the device that signaled it is still in alarm?", a:"No", w:["Yes, always","Yes, by holding RESET for 10 seconds","Only on addressable panels"],
  e:"The panel cannot be reset to normal until the device returns to normal from alarm." },
{ id:"f12", t:"facp", ref:"§6.5", q:"A manual pull station was activated. In what order is the system reset?", a:"Reset the pull station first, then reset at the FACP (at the FDNY's direction)", w:["Reset at the FACP first, then the pull station","Reset only at the pull station","Reset only at the central station"],
  e:"The pull station must be reset to normal before resetting at the main FACP. The FACP is only reset at the direction of the FDNY." },
{ id:"f13", t:"facp", ref:"§6.5", q:"Who may turn off an activated fire alarm?", a:"Only a Certificate of Fitness holder or a Fire Department representative", w:["Any building employee","Any tenant","The central station operator, remotely"],
  e:"The alarm may be turned off only by a Certificate of Fitness holder or a Fire Department representative." },
{ id:"f14", t:"facp", ref:"§3.1", q:"Where should the panel operating instructions be posted?", a:"Next to the FACP", w:["In the building lobby directory","At the central station","In the S-95 holder's car"],
  e:"Get the operations manual and panel instructions. Instructions should be posted next to the FACP." },
{ id:"f15", t:"facp", ref:"§4.5", q:"A carbon monoxide detector connected to the FACP activates. Before the panel can be reset:", a:"The FDNY must determine that carbon monoxide is at safe levels", w:["The S-95 must open the windows for 5 minutes","The central station must approve it","Nothing; reset it immediately"],
  e:"The FDNY must determine CO is at safe levels in the space before the panel can be reset." },
{ id:"f16", t:"facp", ref:"§4.5", q:"How does a smoke detector normally return to normal after an alarm?", a:"It resets when RESET is pressed at the FACP, if the condition that activated it has cleared", w:["It must always be replaced","It must be removed and reinstalled","The central station resets it remotely"],
  e:"Smoke detectors normally reset from the FACP once the condition has cleared." },
{ id:"f17", t:"facp", ref:"§4.5", q:"What must be done with ALL abnormal conditions?", a:"Investigate them and note them in the log book", w:["Silence them and ignore them","Report them only if they repeat","Write them on a sticky note on the panel"],
  e:"ALL ABNORMAL CONDITIONS MUST BE INVESTIGATED AND NOTED IN THE LOG BOOK." },
{ id:"f18", t:"facp", ref:"§3.1", q:"What is the primary purpose of the FACP?", a:"To process signals from initiating devices and activate the appropriate signals and outputs", w:["To extinguish fires","To store the alarm log book electronically","To provide building lighting"],
  e:"The FACP monitors inputs and controls outputs. Its primary purpose is processing signals and activating outputs." },

/* ================= Initiating devices ================= */
{ id:"d1", t:"devices", ref:"§6.1", q:"Compared with heat detectors, smoke detectors:", a:"Detect most fires much more rapidly", w:["Are slower but more reliable","Detect only flaming fires","Never need cleaning"],
  e:"Smoke detectors detect most fires much more rapidly than heat detectors." },
{ id:"d2", t:"devices", ref:"§6.1", q:"Smoke detectors sense particles of combustion that are:", a:"Visible or invisible to the human eye", w:["Only visible","Only invisible","Only larger than 1 inch"],
  e:"They detect visible or invisible particles of combustion." },
{ id:"d3", t:"devices", ref:"§6.1", q:"Most smoke detectors work by optical detection or by a physical process. These are called:", a:"Photoelectric and ionization", w:["Rate-of-rise and fixed temperature","Vane and pressure","Single action and double action"],
  e:"Optical = photoelectric. Physical process = ionization. Multi-sensor detectors use both." },
{ id:"d4", t:"devices", ref:"§6.1", q:"Why do multi-sensor smoke detectors use both photoelectric and ionization methods?", a:"To increase sensitivity to smoke", w:["To detect water leaks","To reduce the cost of the detector","So they never need cleaning"],
  e:"Multi-sensor detectors combine both methods to increase sensitivity." },
{ id:"d5", t:"devices", ref:"§6.1", q:"A smoke detector that could be mechanically damaged must be protected by:", a:"A protective guard listed for use with that detector", w:["Duct tape","A plastic bag","Any metal cage from a hardware store"],
  e:"Guards must be listed for use with that specific detector (NFPA 72)." },
{ id:"d6", t:"devices", ref:"§6.1", q:"When a smoke detector reports to the FACP that it needs maintenance, it must be cleaned within:", a:"1 week", w:["24 hours","30 days","6 months"],
  e:"It must be cleaned within 1 week of the indication." },
{ id:"d7", t:"devices", ref:"§6.1", q:"During construction, when should detector covers be removed?", a:"At the end of each shift or when work stops", w:["Only when the whole project is complete","Never; they stay on permanently","Once a month"],
  e:"Remove covers at the end of each shift or when work stops. Cover only during active dust-generating work." },
{ id:"d8", t:"devices", ref:"§6.1", q:"Construction detector covers should be:", a:"Manufacturer-approved or UL-listed, usually bright red, and still allowing limited airflow", w:["Ordinary plastic bags","Painted directly onto the detector","Made of aluminum foil to block all air"],
  e:"Use listed covers designed for construction. They block dust but allow limited airflow, and are usually red." },
{ id:"d9", t:"devices", ref:"§6.1", q:"Which activity requires covering smoke detectors (with listed covers) while it is happening?", a:"Drywall sanding", w:["Vacuuming carpets","Office meetings","Answering phones"],
  e:"Cover only during dust-generating work: drywall sanding, saw cutting, concrete grinding, spraying paint or texture." },
{ id:"d10", t:"devices", ref:"§6.2", q:"Which heat detector is MORE sensitive?", a:"Rate-of-rise", w:["Fixed-temperature","They are equally sensitive","Neither; heat detectors are not sensitive"],
  e:"The rate-of-rise detector is more sensitive than the fixed-temperature detector." },
{ id:"d11", t:"devices", ref:"§6.2", q:"After a rate-of-rise heat detector activates the fire alarm, it:", a:"Does not have to be replaced", w:["Must always be replaced","Must be sent back to the manufacturer","Must be repainted"],
  e:"Rate-of-rise detectors normally self-restore and don't have to be replaced." },
{ id:"d12", t:"devices", ref:"§6.2", q:"How does a fixed-temperature heat detector work?", a:"A fusible element melts at a preset temperature, allowing two contacts to touch", w:["A beam of light is blocked by smoke","Air is drawn through pipes","A paddle moves in flowing water"],
  e:"Two contacts are separated by a fusible element. When it melts, the contacts meet and the alarm activates." },
{ id:"d13", t:"devices", ref:"§6.2", q:"Which type of heat detector is the most used?", a:"Fixed-temperature", w:["Rate-of-rise","Projected beam","Air sampling"],
  e:"The booklet states fixed-temperature heat detectors are the most used." },
{ id:"d14", t:"devices", ref:"§6.2", q:"Who may test heat detectors?", a:"Only authorized fire alarm technicians", w:["The S-95 holder, using a hair dryer","Any building employee","The FDNY only"],
  e:"Heat detectors can only be tested by authorized technicians. The S-95 makes sure working detectors are in place and calls for repairs." },
{ id:"d15", t:"devices", ref:"§6.2", q:"A heat detector subject to mechanical damage must be protected by:", a:"An approved UL/FM mechanical guard", w:["A cardboard box","A smoke detector cover","Nothing; heat detectors don't need protection"],
  e:"Use an approved UL/FM mechanical guard." },
{ id:"d16", t:"devices", ref:"§6.2", q:"Which heat detectors will usually reset themselves after operating?", a:"Intelligent heat detectors", w:["All fixed-temperature detectors with fusible elements","Only detectors that have been painted","None"],
  e:"Fixed-temperature detectors normally need replacement, but intelligent heat detectors usually reset themselves." },
{ id:"d17", t:"devices", ref:"§6.3", q:"Which statement about the sprinkler waterflow device is TRUE?", a:"It does not turn the water on or off", w:["It opens the sprinkler heads","It shuts off water when the alarm is silenced","It is a supervisory device"],
  e:"The vane or paddle triggers a switch when water flows. The device does not control the water." },
{ id:"d18", t:"devices", ref:"§6.3", q:"Activation of a waterflow device will cause:", a:"The fire alarm to sound, the elevators to recall, and a fire alarm signal to the central station (if monitored)", w:["Only a trouble light at the panel","The water supply to shut off","Only a supervisory signal"],
  e:"Waterflow activation sounds the alarm, recalls elevators, and sends a fire alarm signal to the central station." },
{ id:"d19", t:"devices", ref:"§6.3", q:"When can a waterflow alarm be reset or silenced?", a:"Not until the waterflow condition has stopped", w:["Immediately","After 5 minutes, even if water is flowing","Only by the sprinkler contractor"],
  e:"The system cannot be reset or silenced until the waterflow has stopped." },
{ id:"d20", t:"devices", ref:"§6.4", q:"Carbon monoxide detectors are required in:", a:"Any building with fossil-fuel (gas or oil) burning equipment", w:["Only high-rise buildings","Only buildings with garages","Only hospitals"],
  e:"CO detectors are required in any building with fossil-fuel burning equipment." },
{ id:"d21", t:"devices", ref:"§6.4", q:"A CO detector is in alarm and cannot be reset. What should you assume?", a:"That carbon monoxide is present, and follow life-safety precautions", w:["That the detector is broken and can be ignored","That it is a trouble condition","That the alarm is unnecessary"],
  e:"Until CO is excluded as the source, assume it is present and follow appropriate life-safety precautions." },
{ id:"d22", t:"devices", ref:"§6.5", q:"Where must manual fire alarm boxes (pull stations) be located?", a:"Near the exits, on each floor, conspicuous, unobstructed and accessible", w:["Only in the lobby","Only inside locked closets","Only near the FACP"],
  e:"Pull stations must be near exits throughout the protected area, on each floor." },
{ id:"d23", t:"devices", ref:"§6.5", q:"A pull station that requires you to lift a cover before pulling the lever is a:", a:"Double action station", w:["Single action station","Break-glass-only station","Rate-of-rise station"],
  e:"Double action stations need two steps: first break glass, open a door or lift a cover, then operate the lever." },
{ id:"d24", t:"devices", ref:"§6.5", q:"On a single action pull station:", a:"The cover serves as the lever; pulling it down closes a switch", w:["You must break a glass pane first","You need a key to activate it","It must be activated twice"],
  e:"Single action stations need one step. The cover is the lever." },
{ id:"d25", t:"devices", ref:"§6.5", q:"What does a break-glass station require?", a:"Breaking a small pane of glass with a small metal mallet", w:["A key from the FDNY","A code entered on a keypad","Pressing two buttons at once"],
  e:"A break-glass station is a type of double action device." },
{ id:"d26", t:"devices", ref:"§6.5", q:"Can the fire alarm system be reset at the manual pull station?", a:"No, it must be reset at the main FACP after the station is returned to normal", w:["Yes, always","Yes, with a key","Only on weekends"],
  e:"The system cannot be reset at the pull station. A key or tool may be needed to reset the station itself." },
{ id:"d27", t:"devices", ref:"§6.6", q:"Why might the FDNY require protective covers on manual fire alarm boxes?", a:"To prevent malicious false alarms or protect the box from physical damage", w:["To hide them from view","To keep them from being tested","To make them harder for occupants to use in a fire"],
  e:"Protective covers prevent malicious false alarms and physical damage." },
{ id:"d28", t:"devices", ref:"§6.7", q:"A flammable gas detector connected to the FACP activates. What happens?", a:"A supervisory signal is generated and sent to the central station; no alarm tone sounds on the premises", w:["A fire alarm sounds throughout the building","Nothing; gas detectors aren't monitored","Only a trouble light appears"],
  e:"Gas detectors on the FACP generate supervisory signals. No alarm tone sounds, but the central station notifies the owner and the FDNY." },
{ id:"d29", t:"devices", ref:"§6.7", q:"Why does the central station notify the FDNY when a gas detector activates, even though it is a supervisory signal?", a:"Because a gas leak may cause a fire, explosion, or life-threatening condition", w:["Because all supervisory signals go to the FDNY","Because the building owner asked","It doesn't notify the FDNY"],
  e:"Gas leakage can cause fire or explosion, so the owner and FDNY are notified." },
{ id:"d30", t:"devices", ref:"§6.7", q:"A gas leak is reported in your building. Before the FDNY arrives, you should:", a:"Follow your building's non-fire emergency plan, then comply with FDNY orders when they arrive", w:["Reset the panel","Activate a pull station to evacuate","Turn off the fire alarm panel"],
  e:"A gas leak is a non-fire emergency. Follow the building's non-fire emergency plan." },
{ id:"d31", t:"devices", ref:"§3", q:"A security camera disguised as a smoke detector is installed in a hallway. This is:", a:"Never permitted; it is unlawful to install or keep a non-functioning look-alike fire protection device", w:["Allowed if it is labeled","Allowed in residential buildings","Allowed if the FDNY is told"],
  e:"A non-functioning device that looks like fire protection equipment is never permitted." },
{ id:"d32", t:"devices", ref:"§6", q:"A detector is mounted so high that a man-lift is needed to service it. What must the installer do?", a:"Make sure the building owner understands that this equipment will be needed for future testing and cleaning", w:["Nothing; detectors don't need service","Remove the detector","Paint it red"],
  e:"If special equipment is needed, the installer must make sure the owner understands it will be needed in the future." },
{ id:"d33", t:"devices", ref:"§10.3", q:"According to the NYC Fire Code, manual fire alarm boxes must be what color?", a:"Red", w:["Yellow","Blue","Any color matching the wall"],
  e:"Manual fire alarm boxes must be red." },
{ id:"d34", t:"devices", ref:"§10.4", q:"You find a smoke detector that has been painted. What should you do?", a:"Make a log entry right away and arrange replacement by a qualified technician", w:["Scrape the paint off yourself","Leave it, since it still looks fine","Cover it with a bag"],
  e:"Detectors must never be painted or altered. Log it and arrange replacement." },

/* ================= Related devices & systems ================= */
{ id:"rl1", t:"related", ref:"§8", q:"Which is a supervised condition on a water tank?", a:"Low temperature", w:["High temperature only","Color of the water","Tank paint condition"],
  e:"Water tanks are supervised for low temperature and for high or low water level." },
{ id:"rl2", t:"related", ref:"§8", q:"Which emergency generator conditions are commonly supervised?", a:"Generator running and failure to start", w:["Generator paint color","Generator fuel brand","Generator warranty status"],
  e:"Emergency generator running and failure to start are common supervised conditions." },
{ id:"rl3", t:"related", ref:"§8", q:"Your panel shows only a general supervisory signal, without a location. What should you do?", a:"Inspect each supervised device to find which one is causing the signal", w:["Ignore it","Reset the panel repeatedly","Call 911 for a fire"],
  e:"Some panels show only a general supervisory signal, so each supervised device must be inspected." },
{ id:"rl4", t:"related", ref:"§8.3", q:"A partial/staged evacuation signal activates the audible/visual devices on:", a:"The floor of alarm, the floor above, and the floor below", w:["Every floor of the building","Only the lobby","Only the floor of alarm"],
  e:"Partial/staged: the alarm floor, plus one floor above and one below." },
{ id:"rl5", t:"related", ref:"§8.3", q:"A total/general evacuation signal:", a:"Activates all audible/visual devices throughout the building", w:["Activates only the alarm floor","Activates only strobes","Is sent only to the central station"],
  e:"Total/general turns on all devices throughout the building." },
{ id:"rl6", t:"related", ref:"§8.2", q:"Where is a remote annunciator panel typically located?", a:"Where it is accessible to firefighting crews", w:["In a locked tenant office","On the roof","In the basement boiler room behind the boiler"],
  e:"The remote annunciator is located where firefighters can reach it, and shows the zone or location of the activated device." },
{ id:"rl7", t:"related", ref:"§8.2", q:"In a large building, the fire annunciator may also be associated with:", a:"A smoke purge control panel for building ventilation systems", w:["The building's security cameras","The elevator music system","The parking garage gate"],
  e:"In large buildings the annunciator may be combined with smoke purge controls and emergency communications." },
{ id:"rl8", t:"related", ref:"§3 features", q:"What do FIRE dampers do?", a:"Close when the temperature rises and stay shut to stop fire passing through a barrier", w:["Open to let fresh air in during a fire","Pump water to the sprinklers","Release door holders"],
  e:"Fire dampers close when a rise in temperature occurs and stay shut." },
{ id:"rl9", t:"related", ref:"§3 features", q:"What do SMOKE dampers do?", a:"Open and close when required to provide fresh air or stop the passage of smoke", w:["Melt at a preset temperature","Ring the fire alarm bells","Shut off the sprinkler water"],
  e:"Smoke dampers open or close as needed to provide fresh air or stop smoke." },
{ id:"rl10", t:"related", ref:"§3 features", q:"When connected to the FACP, door release:", a:"Uses a relay to release door holders, so doors close and form a smoke barrier", w:["Locks every door in the building","Opens all exit doors to the street","Unlocks the FACP cabinet"],
  e:"The FACP actuates a relay to release door holders, so doors close to provide a smoke barrier." },
{ id:"rl11", t:"related", ref:"§3 features", q:"Elevator recall on a fire alarm sends elevator cars to:", a:"A designated landing floor", w:["The top floor","The floor where the alarm is","Wherever they happen to be"],
  e:"The fire alarm integrates with the elevator controls to recall cars to a designated landing floor." },
{ id:"rl12", t:"related", ref:"§9", q:"A one-way voice communication system uses:", a:"A microphone at the FACP and speakers in occupied areas", w:["Warden phones at every stairway","Handheld radios only","Text messages to tenants"],
  e:"A one-way (public announcement) system uses a microphone at the FACP and speakers." },
{ id:"rl13", t:"related", ref:"§9", q:"Where are warden phones usually located?", a:"Near exit stairways, with one also at the FACP", w:["Only in the lobby","In each apartment","Only on the roof"],
  e:"Warden phones are placed at several locations, usually near exit stairways, and one must be installed at the FACP." },
{ id:"rl14", t:"related", ref:"§9", q:"The central station transmitter must have:", a:"A primary and a secondary means of communication", w:["Only one phone line","A backup generator inside the transmitter","A key held by the FDNY"],
  e:"The central station transmitter must have primary and secondary means of communication." },
{ id:"rl15", t:"related", ref:"§9", q:"You discover the central station transmitter is malfunctioning. What should you do?", a:"Report it to the FDNY-approved central station company and record it in the log book", w:["Unplug it and plug it back in, without logging it","Wait for the annual inspection","Call the Department of Buildings"],
  e:"Report transmitter malfunctions to the central station company and log them. The central station arranges repairs." },
{ id:"rl16", t:"related", ref:"§9", q:"Who must arrange repairs to a malfunctioning central station transmitter?", a:"The central station company", w:["The FDNY","The building's tenants","The elevator company"],
  e:"The central station company must arrange all repairs as soon as possible." },
{ id:"rl17", t:"related", ref:"§10.5", q:"Where must the central station's telephone number and the account number be located?", a:"On the FACP and the central station transmitter", w:["Only in the owner's office","On the building's front door","Only in the log book"],
  e:"The central station phone number and account number must be on the FACP and the transmitter." },
{ id:"rl18", t:"related", ref:"§9", q:"The central station transmitter retransmits alarm signals to the FDNY's:", a:"Bureau of Fire Communications", w:["Bureau of Fire Prevention","Department of Buildings","Office of Emergency Management"],
  e:"Signals go through the central station to the FDNY's Bureau of Fire Communications." },
{ id:"rl19", t:"related", ref:"§3.3", q:"Which is an example of a fire alarm SUB-SYSTEM?", a:"An FM200 system protecting a server room", w:["The building's main FACP","A portable fire extinguisher","A warden phone"],
  e:"Sub-systems include Halon, FM200, Water Mist, Pre-Action, Range Hood, CO2, Foam, Dry Chemical, Smoke Detection, Clean Air Agents and Thermostatic systems." },
{ id:"rl20", t:"related", ref:"§3.3", q:"Activation of a sub-system must:", a:"Activate the base building audible and visual appliances and notify the FDNY through the base building central station", w:["Only sound a local bell in that room","Do nothing until a technician arrives","Shut down the base building fire alarm system"],
  e:"Sub-systems are interconnected to the base building system and must annunciate their type and location." },
{ id:"rl21", t:"related", ref:"§3.3", q:"What does a sub-system need from the FDNY?", a:"Inspection and testing for a Letter of Approval", w:["Nothing; sub-systems are exempt","Only a phone call","A building permit from the FDNY"],
  e:"Sub-systems are subject to FDNY inspection and testing for a Letter of Approval." },
{ id:"rl22", t:"related", ref:"§7", q:"Sprinkler system installation, testing and repair must be done by a person with which two credentials?", a:"A DOB Master Fire Suppression Piping Contractor license and an FDNY S-12/S-15 Certificate of Fitness", w:["An S-95 and an F-01","An S-98 and a W-96","A Master Electrician license and an S-95"],
  e:"Two licenses are required: a DOB Master Fire Suppression Piping Contractor license and an FDNY Citywide Sprinkler System (S-12/S-15) Certificate of Fitness." },
{ id:"rl23", t:"related", ref:"§8.1", q:"What are notification appliances used for?", a:"To alert people to the need to act, usually to evacuate", w:["To detect smoke","To control sprinkler valves","To record alarms"],
  e:"Bells, horns, speakers, strobes and text displays alert occupants to a fire or other emergency." },
{ id:"rl24", t:"related", ref:"§9", q:"Who must make sure all communication units in the fire alarm system are working correctly?", a:"The Certificate of Fitness holder", w:["The FDNY","The telephone company","The tenants"],
  e:"The certificate holder must make sure all communication units work correctly." },

/* ================= ITM / who does what ================= */
{ id:"i1", t:"itm", ref:"§2", q:"Which duty may an S-95 holder perform?", a:"Visual inspection of smoke detectors and other fire alarm components", w:["Smoke detector cleaning","Programming the fire alarm panel","Replacing low-voltage fire alarm components"],
  e:"The S-95 may do visual inspections only. Testing, cleaning, maintenance and service need other certificates." },
{ id:"i2", t:"itm", ref:"§2", q:"Who may perform smoke detector inspection, testing and cleaning?", a:"S-78/F-78 or S-97/S-98 holders", w:["S-95 holders","Any building employee","F-01 fire guards"],
  e:"Per the chart, the S-78/F-78 and S-97/S-98 may do this, but not the S-95." },
{ id:"i3", t:"itm", ref:"§2", q:"Who may program, service, test, repair or replace low-voltage fire alarm components?", a:"S-97/S-98 holders only", w:["S-95 holders","S-78/F-78 holders","Any licensed electrician without a certificate"],
  e:"Only S-97/S-98 holders may do this work." },
{ id:"i4", t:"itm", ref:"§2", q:"Can an S-78/F-78 holder perform visual inspection of fire alarm components OTHER than smoke detectors?", a:"No", w:["Yes","Only in high-rises","Only with FDNY permission"],
  e:"S-78/F-78 holders may visually inspect smoke detectors only." },
{ id:"i5", t:"itm", ref:"§10.1", q:"How often does the FDNY strongly recommend that fire alarm devices be visually inspected for abnormal conditions?", a:"Daily", w:["Weekly","Monthly","Annually"],
  e:"The FDNY strongly recommends a daily visual inspection by the certificate holder." },
{ id:"i6", t:"itm", ref:"§10.1", q:"Visual inspections of an UNMONITORED fire alarm system must be conducted at a minimum:", a:"Weekly", w:["Daily","Monthly","Annually"],
  e:"Unmonitored systems: weekly at a minimum, by an S-95, F-89, F-80, F-53 or S-98." },
{ id:"i7", t:"itm", ref:"§10.1", q:"Visual inspections of a MONITORED fire alarm system may be conducted:", a:"Annually", w:["Hourly","Weekly","Every 5 years"],
  e:"Monitored systems may be visually inspected annually by an S-95, F-89, F-80, F-53 or S-98." },
{ id:"i8", t:"itm", ref:"§10", q:"For a system NOT connected to a central station, NFPA 72 (Table 14.4.3.2) recommends visual inspection of initiating devices at least:", a:"Semi-annually", w:["Every 5 years","Every 2 years","Once in the system's lifetime"],
  e:"Semi-annual visual inspection (as a minimum) and annual testing of initiating devices." },
{ id:"i9", t:"itm", ref:"§10", q:"Who is authorized to perform service and testing on fire alarm systems?", a:"Only certified technicians holding an S-97 or S-98", w:["Any S-95 holder","The building superintendent","The FDNY only"],
  e:"Only S-97 or S-98 holders are authorized to service and test fire alarm systems." },
{ id:"i10", t:"itm", ref:"§10", q:"Who must record a test or visual inspection in the log book?", a:"The person who physically performed the test or visual inspection", w:["The building owner","The central station operator","Any person on duty later that week"],
  e:"Entries must be made by the person who physically did the test or inspection." },
{ id:"i11", t:"itm", ref:"§10", q:"Which certificate holders are authorized to maintain the log books?", a:"S-95, F-53, F-89/T-89 and F-80", w:["Only S-98","Only the FDNY","Any tenant"],
  e:"S-95, F-53, F-89/T-89 and F-80 holders may maintain the log books." },
{ id:"i12", t:"itm", ref:"§10.4", q:"Conventional smoke detectors on a defined fire alarm system must be cleaned at least:", a:"Once every 6 months", w:["Once a week","Once every 2 years","Once every 5 years"],
  e:"They must be cleaned not less than once every six months." },
{ id:"i13", t:"itm", ref:"§10.4", q:"Analog (intelligent) smoke detectors must be cleaned:", a:"No later than 1 week after an indication that cleaning is needed", w:["Every 6 months, no matter what","Every 10 years","Only after a fire"],
  e:"Analog detectors are cleaned within one week of an indication of the need for cleaning." },
{ id:"i14", t:"itm", ref:"§10.4", q:"Smoke detectors must be tested for smoke entry at least:", a:"Once a year", w:["Once a month","Every 3 years","Every 6 years"],
  e:"Smoke entry testing is required at least once a year." },
{ id:"i15", t:"itm", ref:"§10.4", q:"Conventional smoke detectors must be tested for sensitivity at least:", a:"Once a year", w:["Every 5 years","Every week","Never"],
  e:"Sensitivity testing is at least once a year, except analog detectors, which are tested within 1 week of an indication." },
{ id:"i16", t:"itm", ref:"§4.5, §10.4", q:"Smoke detector cleaning and testing may be done by which certificate holders?", a:"S-78, S-97, or S-98", w:["S-95 only","F-01 or F-03","W-96 only"],
  e:"Smoke detector cleaning and testing is done by S-78, S-97 or S-98 holders." },
{ id:"i17", t:"itm", ref:"§10.4", q:"Is the S-95 holder allowed to clean smoke detectors?", a:"No", w:["Yes, with a vacuum","Yes, if the detector is in a lobby","Yes, once a year"],
  e:"S-95 holders are not allowed to perform smoke detector cleaning." },
{ id:"i18", t:"itm", ref:"§10.4", q:"A smoke detector does not perform to the manufacturer's specifications or NFPA 72. It must be:", a:"Re-calibrated, repaired or replaced", w:["Removed and not replaced","Covered with a bag","Painted"],
  e:"Non-conforming detectors must be re-calibrated, repaired or replaced as required." },
{ id:"i19", t:"itm", ref:"§10.3", q:"How often does the FDNY recommend that manual pull stations be visually inspected?", a:"At least once monthly, where practical", w:["Once every 5 years","Daily, by the FDNY","Never"],
  e:"The FDNY recommends monthly visual inspection of manual stations, with results logged." },
{ id:"i20", t:"itm", ref:"§10.3", q:"A defective manual pull station is found. What should happen?", a:"It must be replaced immediately by qualified personnel", w:["Wait for the annual test","Remove it permanently","Tape it shut"],
  e:"Defective devices must be replaced immediately by qualified personnel." },
{ id:"i21", t:"itm", ref:"§10.3", q:"Manual pull stations may also be used to:", a:"Conduct fire drills", w:["Turn on the lobby lights","Reset the FACP","Silence trouble signals"],
  e:"Manual stations may be used to conduct fire drills (with the system taken off-line first)." },
{ id:"i22", t:"itm", ref:"§10.1", q:"What is the purpose of the visual inspection?", a:"To detect defective components", w:["To replace batteries","To program the panel","To clean detectors"],
  e:"The purpose of visual inspection is to detect defective components." },
{ id:"i23", t:"itm", ref:"§10.1", q:"An impairment is found during a visual inspection. What may be required?", a:"Fire guard coverage, in accordance with the Fire Code (see F-01)", w:["Nothing","Immediate demolition of the building","A new Certificate of Occupancy"],
  e:"If an impairment is found, fire guard coverage may be required." },
{ id:"i24", t:"itm", ref:"§10.4", q:"Where can you find a list of approved smoke detector maintenance companies?", a:"On the FDNY website (updated monthly)", w:["In the yellow pages","On the FACP door","From the central station only"],
  e:"The FDNY provides a monthly list of approved companies on its website." },
{ id:"i25", t:"itm", ref:"§2", q:"Which statement about certificate scopes is TRUE?", a:"S-97/S-98 holders may do S-78/F-78 duties, but S-78/F-78 holders cannot do S-97/S-98 duties", w:["S-78 holders may do all S-98 duties","S-95 holders may do all S-97 duties","All certificates have the same scope"],
  e:"Holders of each category must know their limits. The higher certificates cover the lower, not the reverse." },

/* ================= Records ================= */
{ id:"l1", t:"records", ref:"§10.2(1)", q:"Where must the alarm log book be maintained?", a:"On the premises, at the building's main fire alarm control panel", w:["At the central station","At the fire alarm company's office","At the FDNY borough office"],
  e:"It must be on the premises at the main FACP. If there's no secure spot there, it may be locked elsewhere during non-business hours, but must be available to responding FDNY." },
{ id:"l2", t:"records", ref:"§10.2(2)", q:"What type of book must the alarm log book be?", a:"A bound book (not spiral bound) with consecutively numbered, lined pages", w:["A spiral notebook","A loose-leaf binder","Any notepad"],
  e:"Bound (other than spiral bound), with consecutively numbered and lined pages." },
{ id:"l3", t:"records", ref:"§10.2(2)", q:"What must the cover of the log book say?", a:"\"ALARM LOG BOOK\", with the building's name and address", w:["The S-95 holder's name only","\"PRIVATE\"","The central station's logo"],
  e:"The cover must bear the inscription ALARM LOG BOOK, with the building's name and address." },
{ id:"l4", t:"records", ref:"§10.2(2)", q:"How long must alarm log books be kept?", a:"3 years from the date of the last entry", w:["1 year","5 years from the first entry","Until the book is full"],
  e:"Log books must be retained for three years from the date of the last entry." },
{ id:"l5", t:"records", ref:"§10.2(2)", q:"How often must a new alarm log book be started?", a:"Each calendar year (a separate book for each year)", w:["Every month","Every 3 years","Only when the old one is lost"],
  e:"A separate log book must be kept for each calendar year." },
{ id:"l6", t:"records", ref:"§10.2(2)", q:"How must log book entries be made?", a:"In ink and dated", w:["In pencil","Typed on loose paper","On a whiteboard"],
  e:"All entries must be made in ink and dated, in chronological order." },
{ id:"l7", t:"records", ref:"§10.2(3)", q:"How many sections must the alarm log book be divided into?", a:"4", w:["2","3","6"],
  e:"Four sections: (A) Daily, (B) System off-line, (C) Activated alarm, (D) Notification." },
{ id:"l8", t:"records", ref:"§10.2(3)", q:"Each log book section must have enough pages for entries for at least:", a:"One year", w:["One month","Six months","Five years"],
  e:"Each section must have enough pages for at least one year." },
{ id:"l9", t:"records", ref:"§10.2(3)", q:"Which is NOT one of the four required log book sections?", a:"Tenant complaint entries", w:["Daily entries","System off-line entries","Activated alarm entries"],
  e:"The four sections are Daily, System off-line, Activated alarm, and Notification." },
{ id:"l10", t:"records", ref:"§10.2(3)(A)", q:"Daily entries must include:", a:"The certificate holder's name and number, and the time the tour of duty started and when relieved", w:["The outdoor weather","The number of tenants in the building","The central station's account balance"],
  e:"Daily columns: certificate holder's name, certificate number, time started, time relieved, plus action taken on any abnormal condition." },
{ id:"l11", t:"records", ref:"§10.2(3)(C)", q:"Activated alarm entries must include:", a:"Date and time, location and detector type, probable cause, and the FDNY unit and officer who responded", w:["Only the date","Only the name of the person who pulled the station","The cost of the FDNY response"],
  e:"Example: smoke detector, 27th floor, elevator lobby; probable cause; Engine number and officer." },
{ id:"l12", t:"records", ref:"§10.2(3)(B)", q:"System off-line entries must include:", a:"Date and time off-line, the reason, central station name and phone number (or other proof of notification), and date and time restored", w:["Only the time restored","Only the technician's phone number","Nothing; off-line events are not recorded"],
  e:"These are the off-line entry requirements in Fire Rule 907-01, as given in the booklet." },
{ id:"l13", t:"records", ref:"§10.2(3)(D)", q:"Notification entries record:", a:"The date and time of any notification to occupants about a non-functioning or improperly functioning alarm system", w:["Calls from tenants about noise","Notifications from the central station about billing","FDNY inspection appointments"],
  e:"Section (D) covers notifications to occupants about an alarm system that isn't working properly." },
{ id:"l14", t:"records", ref:"§10.2", q:"What must every log book entry include about the person who made it?", a:"Their name and Certificate of Fitness number", w:["Their home address","Their date of birth","Only their initials"],
  e:"All entries must include the name and certificate number of the holder who made the entry." },
{ id:"l15", t:"records", ref:"§10.2", q:"An S-98 technician services the system and makes a log entry. Who is still responsible for supervising the entries and the log book?", a:"The S-95 holder", w:["The S-98 technician only","The FDNY","The central station"],
  e:"The S-95 is responsible for supervising entries and maintaining the alarm log book." },
{ id:"l16", t:"records", ref:"§10.2(2)", q:"Which information must be at the beginning of the log book?", a:"The central station's account number, company name, phone number and supervisor's name", w:["The building's annual revenue","The tenant list","The names of all FDNY firefighters"],
  e:"The front of the book has the building address, FDNY approval date and system type/manufacturer, central station information, and maintenance contractor information." },
{ id:"l17", t:"records", ref:"§10.2(2)", q:"How does the FSP (fire safety and evacuation plan) log book relate to the alarm log book?", a:"It is a different log book; it may be bound with the alarm log book but must be properly labeled and divided", w:["It is the same book","It replaces the alarm log book","It is kept by the FDNY"],
  e:"The FSP log book is separate. It can be bound together with the alarm log book only if labeled and divided." },
{ id:"l18", t:"records", ref:"§10.2(1)", q:"There is no secure location at the main FACP. What may be done with the log book during non-business hours?", a:"It may be secured in another area, as long as it is available to FDNY representatives responding to an alarm", w:["It may be taken home","It may be left on the floor","It may be destroyed and rewritten"],
  e:"It can be secured elsewhere during non-business hours if it is available to responding FDNY." },
{ id:"l19", t:"records", ref:"§10.2(3)", q:"Log book entries must be made in what order?", a:"Chronological order", w:["Alphabetical order","Any order","Order of importance"],
  e:"Entries must be made in chronological order." },
{ id:"l20", t:"records", ref:"§10.2(3)(C)", q:"In which log book section is testing of manual stations by an S-97/S-98 also recorded?", a:"Activated alarm entries", w:["Daily entries","Notification entries","No section"],
  e:"The activated alarm section should also include manual station testing done by an S-97/S-98." },

/* ================= Off-line / out-of-service ================= */
{ id:"o1", t:"oos", ref:"§10.6", q:"Before a fire drill where the alarm will be activated, what must the S-95 do?", a:"Take the system off-line by notifying the FDNY-approved central station beforehand", w:["Call 911 to tell them about the drill","Turn off the FACP power","Nothing; drills don't send signals"],
  e:"Any time the alarm will be activated for a test, inspection or fire drill, notify the central station first." },
{ id:"o2", t:"oos", ref:"§10.6", q:"When is it NOT necessary to take the system off-line?", a:"When speaker audibility tests are being conducted", w:["During fire drills","During smoke detector testing","During pull station testing"],
  e:"Taking the system off-line is not necessary for speaker audibility tests." },
{ id:"o3", t:"oos", ref:"§10.6", q:"Why must the system be taken off-line before testing?", a:"To prevent the unnecessary dispatching of the Fire Department", w:["To save electricity","To make the test go faster","To reset the batteries"],
  e:"Taking the system off-line prevents unnecessary FDNY dispatch." },
{ id:"o4", t:"oos", ref:"§10.7", q:"When a required fire protection system is out of service, the Fire Department must be notified:", a:"Immediately", w:["Within 24 hours","Within 1 week","At the next annual inspection"],
  e:"The Fire Department must be notified immediately." },
{ id:"o5", t:"oos", ref:"§10.7", q:"Unless otherwise directed by the FDNY, what must be done while a required fire protection system is out of service?", a:"Either evacuate the building or keep a fire watch by Certificate of Fitness fire guards", w:["Nothing until repairs are complete","Post a sign at the front desk only","Ask tenants to keep an eye out"],
  e:"Either the building must be evacuated, or a fire watch must be maintained by certified fire guards." },
{ id:"o6", t:"oos", ref:"§10.7", q:"What is the fire guard's ONLY duty?", a:"Constant patrols of the protected premises, keeping watch for fires", w:["Repairing the fire alarm","Working the front desk","Cleaning smoke detectors"],
  e:"A fire guard's only duty is constant patrol, and they must have at least one approved way to notify the FDNY." },
{ id:"o7", t:"oos", ref:"§10.7", q:"Fire guards must be provided with:", a:"At least one approved means of notifying the Fire Department", w:["A key to reset the FACP","A fire extinguisher only","A master key to all apartments"],
  e:"Fire guards need at least one approved means of notifying the FDNY." },
{ id:"o8", t:"oos", ref:"§10.7", q:"A pull station is found defective. Besides notifying your supervisor, what must you do?", a:"Put a placard over the defective box indicating that it is out of service", w:["Remove the pull station","Paint over it","Ignore it until the annual test"],
  e:"The certificate holder must notify the supervisor and place an out-of-service placard over the defective box." },
{ id:"o9", t:"oos", ref:"§10.7", q:"Who designates the impairment coordinator?", a:"The owner, managing agent or tenant of the premises", w:["The FDNY","The central station","The Department of Buildings"],
  e:"The owner, managing agent or tenant must designate an impairment coordinator." },
{ id:"o10", t:"oos", ref:"§10.7", q:"If no impairment coordinator has been designated, who is considered the impairment coordinator?", a:"The owner", w:["The S-95 holder","The FDNY","The central station"],
  e:"In the absence of a specific designee, the owner is the impairment coordinator." },
{ id:"o11", t:"oos", ref:"§10.7", q:"What is the role of the impairment coordinator?", a:"To make sure proper notification and safety precautions are taken when a fire protection system is out of service", w:["To install new fire alarm systems","To dispatch fire trucks","To test smoke detectors"],
  e:"This is how the booklet defines the impairment coordinator." },
{ id:"o12", t:"oos", ref:"§10.7", q:"What is the non-emergency FDNY number for out-of-service notifications in Manhattan?", a:"(212) 570-4300", w:["(718) 965-8300","911","311 only"],
  e:"Manhattan (212) 570-4300 · Brooklyn (718) 965-8300 · Queens (718) 476-6200 · Bronx (718) 430-0200 · Staten Island (718) 494-4296." },
{ id:"o13", t:"oos", ref:"§10.7", q:"What is the non-emergency FDNY number for out-of-service notifications in Brooklyn?", a:"(718) 965-8300", w:["(718) 476-6200","(718) 430-0200","(212) 570-4300"],
  e:"Brooklyn: (718) 965-8300." },
{ id:"o14", t:"oos", ref:"§10.7", q:"What is the non-emergency FDNY number for out-of-service notifications in Queens?", a:"(718) 476-6200", w:["(718) 494-4296","(718) 965-8300","(212) 570-4300"],
  e:"Queens: (718) 476-6200." },
{ id:"o15", t:"oos", ref:"§10.7", q:"What is the non-emergency FDNY number for out-of-service notifications in the Bronx?", a:"(718) 430-0200", w:["(718) 476-6200","(718) 494-4296","(212) 570-4300"],
  e:"Bronx: (718) 430-0200." },
{ id:"o16", t:"oos", ref:"§10.7", q:"What is the non-emergency FDNY number for out-of-service notifications in Staten Island?", a:"(718) 494-4296", w:["(718) 430-0200","(718) 965-8300","(212) 570-4300"],
  e:"Staten Island: (718) 494-4296." },
{ id:"o17", t:"oos", ref:"§10.7", q:"Which is NOT required in an out-of-service notification to the FDNY?", a:"The building's annual electric bill", w:["The estimated time until the system is operational","The floors or areas where the system is out of service","The name and certificate number of the holder responsible for the system"],
  e:"There are 8 required items: caller name and phone; address and occupancy; system type; condition description; affected floors or areas; estimated time to restore; status of other systems; responsible holder's name and certificate number." },
{ id:"o18", t:"oos", ref:"§10.7", q:"A defect is not corrected at the end of a system inspection. Who must be informed of the impairment immediately?", a:"The system owner or the owner's representative", w:["Only the tenants","No one until the next inspection","The fire alarm manufacturer"],
  e:"If a defect isn't corrected at the end of an inspection, test or maintenance visit, the owner or their representative must be informed immediately." },
{ id:"o19", t:"oos", ref:"§10.7", q:"The owner must also be notified when:", a:"An impairment period is completed or discontinued", w:["The central station changes operators","A tenant moves out","The log book is full"],
  e:"The owner must be notified when an impairment starts and when it is completed or discontinued." },
{ id:"o20", t:"oos", ref:"§10.7", q:"Which of these is included in 'fire protection systems' for impairment purposes?", a:"The fire command center and its components, standpipe systems and sprinkler systems", w:["Only portable fire extinguishers","Only the building's elevators","Only exit signs"],
  e:"Fire protection systems include, but aren't limited to, the fire command center, standpipes and sprinklers." },
{ id:"o21", t:"oos", ref:"§10.7", q:"Which certificate must people keeping a fire watch for an out-of-service system hold?", a:"A Certificate of Fitness for Fire Guard (F-01, Fire Guard for Impairment)", w:["S-95","W-96","S-12"],
  e:"Fire watch must be kept by people holding a Certificate of Fitness for Fire Guard." },
{ id:"o22", t:"oos", ref:"§10.7", q:"The impairment coordinator's responsibilities include:", a:"Posting a fire guard detail, notifying tenants, and posting out-of-service signs when appropriate", w:["Repairing the fire alarm panel","Approving new fire alarm designs","Issuing FDNY violations"],
  e:"The impairment coordinator handles the fire guard, tenant notifications and signage, and notifies the FDNY immediately." },

/* ================= Unnecessary / unwarranted ================= */
{ id:"u1", t:"unnecessary", ref:"§6.8", q:"Who is responsible for preventing unnecessary or unwarranted alarms and is liable for violations?", a:"The owner of the building (including any lessee)", w:["The FDNY","The central station only","The fire alarm manufacturer"],
  e:"The owner, including any lessee, is responsible and liable." },
{ id:"u2", t:"unnecessary", ref:"§6.8", q:"It is unlawful to transmit how many unnecessary or unwarranted alarms in any three-month period?", a:"Two or more", w:["One or more","Three or more","Five or more"],
  e:"It is unlawful to transmit two or more in any three-month period." },
{ id:"u3", t:"unnecessary", ref:"§6.8", q:"The owner will be subject to a violation when which unnecessary or unwarranted alarm is transmitted in a three-month period?", a:"The second", w:["The first","The third","The fifth"],
  e:"A second unnecessary or unwarranted alarm within three months leads to a violation." },
{ id:"u4", t:"unnecessary", ref:"§6.8", q:"After receiving the first violation, what can the owner do?", a:"Address the cause and certify correction without an OATH hearing and without a penalty", w:["Nothing; a fine is automatic","Appeal to the central station","Must close the building"],
  e:"The first violation can be certified as corrected (Fire Rule 109-01(c)) without a hearing or penalty." },
{ id:"u5", t:"unnecessary", ref:"§6.8", q:"After a violation is issued, for how long is the owner liable for ANY subsequent unnecessary or unwarranted alarm?", a:"6 months from the date the violation was issued", w:["3 months","1 year","1 month"],
  e:"The owner is liable for any subsequent alarm within six months of the violation." },
{ id:"u6", t:"unnecessary", ref:"§6.8", q:"A subsequent violation within the liability period is:", a:"A repeat offense, not eligible for certification of correction without a hearing and penalty", w:["Automatically dismissed","Eligible for certification with no penalty","Only a warning"],
  e:"Each subsequent violation is a repeat offense (Admin. Code §15-229(a)), and it extends liability another 6 months." },
{ id:"u7", t:"unnecessary", ref:"§6.8", q:"How does an owner return to compliant status after a violation?", a:"By not transmitting any unnecessary or unwarranted alarm for 6 months after the last violation", w:["By paying a fee","By changing central stations","By getting a new S-95"],
  e:"Six clean months restores compliant status, with the original 2-in-3-months threshold." },
{ id:"u8", t:"unnecessary", ref:"§6.8", q:"A malicious false alarm transmitted by activating a manual fire alarm box is:", a:"Not considered an unnecessary alarm", w:["Counted as two unnecessary alarms","Counted as an unwarranted alarm","An automatic violation for the S-95"],
  e:"Malicious pull station alarms are not counted as unnecessary alarms." },
{ id:"u9", t:"unnecessary", ref:"§4.5 note", q:"Which is a common cause of false smoke detector alarms listed in the study material?", a:"Dust from cutting wood, sheetrock or sanding", w:["Normal office lighting","Cold weather","Elevator music"],
  e:"Dust from cutting wood, sheetrock or sanding, and detectors that haven't been cleaned, cause false alarms." },
{ id:"u10", t:"unnecessary", ref:"§1.1", q:"Smoke from a lit cigarette sets off a detector in a non-smoking area. The system worked correctly. This is a(n):", a:"Unnecessary alarm", w:["Unwarranted alarm","Supervisory signal","Trouble signal"],
  e:"This is the booklet's own example of an unnecessary alarm." },
{ id:"u11", t:"unnecessary", ref:"§1.1", q:"A control panel malfunction causes an alarm. This is a(n):", a:"Unwarranted alarm", w:["Unnecessary alarm","Malicious alarm","Valid fire alarm"],
  e:"Panel malfunction is listed as an example of an unwarranted alarm." },
{ id:"u12", t:"unnecessary", ref:"§6.8", q:"Which Fire Rule governs unnecessary and unwarranted alarm limits?", a:"Fire Rule 907-01", w:["Fire Rule 101-01","Fire Rule 3401-01","Fire Rule 501-01"],
  e:"The limits are in Fire Rule 907-01(c). Certification of correction is under 109-01(c)." },

/* ================= Portable fire extinguishers ================= */
{ id:"e1", t:"pfe", ref:"§11", q:"A portable fire extinguisher must be located within how many feet of commercial cooking equipment?", a:"30 feet", w:["10 feet","50 feet","75 feet"],
  e:"Portable fire extinguishers are required within 30 feet of commercial cooking equipment." },
{ id:"e2", t:"pfe", ref:"§11", q:"Class A fires involve:", a:"Ordinary combustibles such as wood, cloth, paper, rubber and many plastics", w:["Flammable liquids","Energized electrical equipment","Combustible metals"],
  e:"Class A covers ordinary combustible materials." },
{ id:"e3", t:"pfe", ref:"§11", q:"Class B fires involve:", a:"Flammable liquids, combustible liquids, greases, oils, solvents and flammable gases", w:["Paper and wood","Cooking oils in commercial kitchens only","Magnesium and titanium"],
  e:"Class B covers flammable and combustible liquids, petroleum greases, tars, oils, oil-based paints, solvents, lacquers, alcohols and flammable gases." },
{ id:"e4", t:"pfe", ref:"§11", q:"Class C fires involve:", a:"Energized electrical equipment", w:["Combustible metals","Cooking oils","Ordinary combustibles"],
  e:"Class C covers fires that involve energized electrical equipment." },
{ id:"e5", t:"pfe", ref:"§11", q:"Class D fires involve:", a:"Combustible metals such as magnesium, titanium, zirconium, sodium and potassium", w:["Cooking fats","Gasoline","Electrical panels"],
  e:"Class D covers combustible metals." },
{ id:"e6", t:"pfe", ref:"§11", q:"Class K fires involve:", a:"Cooking appliances with combustible cooking media (vegetable or animal oils and fats)", w:["Kerosene heaters","Electrical equipment","Wood and paper"],
  e:"Class K covers combustible cooking media." },
{ id:"e7", t:"pfe", ref:"§11.1", q:"How long and wide is the real hologram strip on an FDNY PFE tag?", a:"3 inches long by ¼ inch wide", w:["1 inch by 1 inch","6 inches by ½ inch","2 inches by 2 inches"],
  e:"A real hologram strip is 3 inches long by ¼ inch wide, and changes color as it moves against the light." },
{ id:"e8", t:"pfe", ref:"§11.1", q:"What are the two ways the FDNY recommends to verify a PFE tag?", a:"The hologram and the QR code", w:["The tag color and the price","The serial number and the weight","The barcode and the signature"],
  e:"Check the hologram, and scan the QR code to reach the current list of FDNY-approved companies." },
{ id:"e9", t:"pfe", ref:"§11.1", q:"You suspect a fire extinguisher tag is counterfeit. Whom should you contact?", a:"The FDNY, by email at Tags.Decal@fdny.nyc.gov", w:["The extinguisher's manufacturer only","The central station","No one"],
  e:"If you suspect a counterfeit, contact the FDNY immediately at Tags.Decal@fdny.nyc.gov. If you just can't verify a tag, contact your supervisor." },
{ id:"e10", t:"pfe", ref:"§11.2", q:"How often must portable fire extinguishers get a 'quick check'?", a:"Monthly", w:["Daily","Annually","Every 5 years"],
  e:"A monthly quick check is required, done by a person the business owner selects." },
{ id:"e11", t:"pfe", ref:"§11.2", q:"Which item is part of the monthly quick check?", a:"The extinguisher is fully charged and in its designated place", w:["The extinguisher is hydrostatically tested","The extinguisher is repainted","The extinguisher is discharged and refilled"],
  e:"Quick check: fully charged; in its designated place; not actuated or tampered with; no obvious damage." },
{ id:"e12", t:"pfe", ref:"§11.2", q:"Where is the monthly quick check record kept?", a:"On the back of the PFE tag, or by an approved permanent electronic method", w:["In the alarm log book only","At the central station","Nowhere; it does not need to be recorded"],
  e:"Record the date and the inspector's name or initials on the back of the tag or electronically." },
{ id:"e13", t:"pfe", ref:"§11.2", q:"Who must perform the annual inspection of portable fire extinguishers?", a:"A W-96 Certificate of Fitness holder from an FDNY-approved company", w:["The S-95 holder","Any tenant","The FDNY"],
  e:"A W-96 holder from an FDNY-approved company does the annual inspection and replaces the PFE tag." },
{ id:"e14", t:"pfe", ref:"§11", q:"On structures under construction, alteration or demolition, portable fire extinguishers are required:", a:"On each floor (except detached Group R-3 occupancies)", w:["Only on the ground floor","Only on the top floor","Not at all"],
  e:"Extinguishers are required on each floor of construction, alteration or demolition sites, except detached R-3." },

/* ================= Lithium-ion ================= */
{ id:"li1", t:"liion", ref:"§12", q:"Charging more than how many personal mobility devices requires a dedicated room with ventilation and a self-closing door?", a:"5", w:["2","10","20"],
  e:"Charging more than five personal mobility devices or their removable batteries needs a dedicated, ventilated room with a self-closing door." },
{ id:"li2", t:"liion", ref:"§12", q:"For a total battery capacity of 20 kWh, what separation is required between charging batteries?", a:"2 feet", w:["6 inches","3 feet","10 feet"],
  e:"20 kWh: 2-foot separation. Up to 50 kWh: 3-foot separation." },
{ id:"li3", t:"liion", ref:"§12", q:"For a total battery capacity up to 50 kWh, what separation is required between charging batteries?", a:"3 feet", w:["1 foot","2 feet","5 feet"],
  e:"Up to 50 kWh needs a 3-foot separation." },
{ id:"li4", t:"liion", ref:"§12", q:"Do portable fire extinguishers work on lithium-ion battery fires?", a:"No", w:["Yes, any type works","Yes, but only water extinguishers","Only Class C extinguishers work"],
  e:"The booklet states that fire extinguishers do not work on lithium-ion battery fires." },
{ id:"li5", t:"liion", ref:"§12", q:"In the event of a lithium-ion battery fire, you should:", a:"Leave, close the door, and call 911 once you are in a safe location", w:["Fight it with a fire extinguisher","Pour water on it and stay","Carry the device outside"],
  e:"Leave and CLOSE the door. Call 911 once you are safe." },
{ id:"li6", t:"liion", ref:"§12", q:"Which is a correct lithium-ion charging practice?", a:"Plug directly into a wall electrical outlet", w:["Plug into a power strip","Charge overnight on your bed","Use any aftermarket charger that fits"],
  e:"Always plug directly into a wall outlet. Never use power strips or overload outlets." },
{ id:"li7", t:"liion", ref:"§12", q:"How should used lithium-ion batteries be disposed of?", a:"At a NYC battery recycling center; putting them in the trash or recycling bin is illegal", w:["In the regular trash","In the blue recycling bin","Burned in the boiler"],
  e:"Never place batteries in the trash or recycling bin. Visit nyc.gov/batteries for disposal locations." },
{ id:"li8", t:"liion", ref:"§12", q:"After all visible fire is out, a lithium-ion battery:", a:"May unexpectedly re-ignite minutes, hours or even days later", w:["Is completely safe","Can be recharged immediately","Can be thrown in the trash"],
  e:"Re-ignition is common, because batteries can enter an uncontrollable self-heating state." },
{ id:"li9", t:"liion", ref:"§12", q:"What is the most suitable charge level for lithium-ion batteries?", a:"A partial charge", w:["Always 100%","Always fully drained before charging","Overcharged above 100%"],
  e:"Lithium-ion batteries don't need to be fully charged. A partial charge is most suitable." },
{ id:"li10", t:"liion", ref:"§12", q:"Why must you use the OEM (original) charger with a lithium-ion battery?", a:"It works with the battery management system (BMS); the wrong combination may defeat the overcharge cutoff", w:["It charges faster","It is cheaper","It makes the battery waterproof"],
  e:"A wrong battery and charger combination may not stop charging at 100%, creating fire and explosion hazards." },
{ id:"li11", t:"liion", ref:"§12", q:"Which sign means you should immediately stop using or charging a battery and call 911?", a:"A change in color or shape", w:["The battery is at 50%","The device is new","The charger light is green"],
  e:"Stop and call 911 for fire or smoke, overheating, a change in color or shape, odd noises, leaking, or a strange smell." },
{ id:"li12", t:"liion", ref:"§12", q:"Lithium-ion powered devices should be certified by a:", a:"Nationally Recognized Testing Laboratory (NRTL)", w:["Local hardware store","Central station company","Building superintendent"],
  e:"Always buy and use devices certified by an NRTL, such as UL." }
];
